<?php declare(strict_types=1);
namespace Modules\PromptEngine\Services;
use Modules\PromptEngine\DTOs\{CharacterAnalysisData,CharacterInputData,DesignPlanData,PlatformPromptData}; use Modules\PromptEngine\Exceptions\UnsupportedPlatformException; use Modules\PromptEngine\Interfaces\{PlatformPromptProviderInterface,PromptGeneratorInterface};
final class PromptAssemblerService implements PromptGeneratorInterface { private array $providers=[]; public function __construct(iterable $providers){foreach($providers as $p)if($p instanceof PlatformPromptProviderInterface)$this->providers[$p->platform()]=$p;} public function generate(CharacterInputData $input,CharacterAnalysisData $analysis,DesignPlanData $plan):PlatformPromptData{$provider=$this->providers[$input->platform]??throw new UnsupportedPlatformException('Unsupported prompt platform.');$out=$provider->build(['analysis'=>$analysis->toArray(),'plan'=>$plan->toArray(),'style'=>$input->style,'aspect_ratio'=>$input->aspectRatio,'text_mode'=>$input->textMode]);return new PlatformPromptData($input->platform,$out['prompt'],$out['negative_prompt']??'',array_merge($out['recommended_settings']??[],isset($out['positive_prompt'])?['positive_prompt'=>$out['positive_prompt']]:[]));} }
